151→// todoWriteToolInput represents the tool_input structure for the TodoWrite tool.
152→// Used to extract the todos array which is then passed to strategy.ExtractInProgressTodo.
153→type todoWriteToolInput struct {
154→	Todos json.RawMessage `json:"todos"`
155→}
156→
157→// ExtractTodoContentFromToolInput extracts the content of the in-progress todo item from TodoWrite tool_input.
158→// Falls back to the first pending item if no in-progress item is found.
159→// Returns empty string if no suitable item is found or JSON is invalid.
160→//
161→// This function unwraps the outer tool_input object to extract the todos array,
162→// then delegates to strategy.ExtractInProgressTodo for the actual parsing logic.
163→func ExtractTodoContentFromToolInput(toolInput json.RawMessage) string {
164→	if len(toolInput) == 0 {
165→		return ""
166→	}
167→
168→	// First extract the todos array from tool_input
169→	var input todoWriteToolInput
170→	if err := json.Unmarshal(toolInput, &input); err != nil {
171→		return ""
172→	}
173→
174→	// Delegate to strategy package for the actual extraction logic
175→	return strategy.ExtractInProgressTodo(input.Todos)
176→}
177→
178→// ExtractLastCompletedTodoFromToolInput extracts the content of the last completed todo item.
179→// In PostToolUse[TodoWrite], the tool_input contains the NEW todo list where the
180→// just-finished work is marked as "completed". The last completed item represents
181→// the work that was just done.
182→//
183→// Returns empty string if no completed items exist or JSON is invalid.
184→func ExtractLastCompletedTodoFromToolInput(toolInput json.RawMessage) string {
185→	if len(toolInput) == 0 {
186→		return ""
187→	}
188→
189→	// First extract the todos array from tool_input
190→	var input todoWriteToolInput
191→	if err := json.Unmarshal(toolInput, &input); err != nil {
192→		return ""
193→	}
194→
195→	// Delegate to strategy package for the actual extraction logic
196→	return strategy.ExtractLastCompletedTodo(input.Todos)
197→}
198→
199→// CountTodosFromToolInput returns the number of todo items in the TodoWrite tool_input.
200→// Returns 0 if the JSON is invalid or empty.
201→//
202→// This function unwraps the outer tool_input object to extract the todos array,
203→// then delegates to strategy.CountTodos for the actual count.
204→func CountTodosFromToolInput(toolInput json.RawMessage) int {
205→	if len(toolInput) == 0 {
206→		return 0
207→	}
208→
209→	// First extract the todos array from tool_input
210→	var input todoWriteToolInput
211→	if err := json.Unmarshal(toolInput, &input); err != nil {
212→		return 0
213→	}
214→
215→	// Delegate to strategy package for the actual count
216→	return strategy.CountTodos(input.Todos)
217→}
